#!/usr/bin/env bash
# PT-GATE-D evidence (plan section 10, item 7), into docs/evidence/f01-playtest/:
#   1. 640x400 (`--deck`) at-speed GIFs of the five abilities regenerated by PT-GATE-B (chain, reflex,
#      Magic Missile, Light on Your Feet, Puddle Jumper), of Donut's agile motion (the run race and the
#      jump race) and of the dynamite ring (outer launch), each window against headless, generated
#      twice and compared byte for byte (deck-*.gif);
#   2. room 4's spectacular route (`--room-pilot haz_spectacular`: a dynamite throw whose blast lights
#      the latched Rot Sticker) at 640x360 and 640x400, window against headless and against the timed
#      live loop, generated twice and compared (route-room4-spectacular*.gif);
# The room 6 and perf files are scripts/make_f01_gate_b_evidence.sh and the two perf scripts; the render-loop
# replay is scripts/make_f01_gate_d_replay.sh; the human-default-path session is scripts/make_f01_gate_d_session.sh.
# Needs the debug binary (cargo build --locked --bin floor01_scene), the exported atlases
# (bash scripts/export_assets.sh), xvfb-run and Pillow. Runs the windows one after the other.
#   BIN=<floor01_scene>   CAPTURES: a scratch dir under artifacts/ (deleted first)
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
export BIN="${BIN:-./target/debug/floor01_scene}"
caps="${CAPTURES:-artifacts/f01-gate-d-captures}"
for dir in "$caps"; do
  case "$dir" in
    artifacts/?*) ;;
    *) echo "refusing scratch dir '$dir': it must be a path under artifacts/" >&2; exit 2 ;;
  esac
done
out=docs/evidence/f01-playtest
rm -rf "$caps"
mkdir -p "$caps" "$out"
rm -f "$out"/deck-*.gif "$out"/route-room4-spectacular*.gif "$out/capture_lines_d.txt"
xvfb() { xvfb-run -a -s '-screen 0 1280x720x24' "$@"; }
last_state() { grep '^COMBAT_STATE ' "$1" | tail -n 1 | sed -E 's/.* hash=([0-9a-f]+).*/\1/'; }
: > "$out/capture_lines_d.txt"

# 1. The 640x400 GIFs of the fixtures, two passes.
fixture_gif() { # pass name fixture first:step:count step_ticks
  local pass="$1" name="$2" fx="$3" seq="$4" step="$5" dir="$caps/$1/$2"
  local first count last
  IFS=: read -r first _ count <<<"$seq"
  last=$((first + step * (count - 1)))
  mkdir -p "$dir"
  xvfb "$BIN" --scale 1 --deck --party-fixture "$fx" --capture-sequence "$seq" --capture-dir "$dir" > "$dir/run.log" 2>&1
  "$BIN" --headless-floor01-smoke --deck --party-fixture "$fx" --capture-tick "$last" > "$dir/headless.log" 2>&1
  local w h match=no
  w="$(last_state "$dir/run.log")"; h="$(last_state "$dir/headless.log")"
  [[ -n "$w" && "$w" == "$h" ]] && match=yes
  [[ "$pass" == a ]] && echo "GATE_D_CAPTURE name=$name fixture=$fx view=640x400 first_tick=$first step=$step last_tick=$last window_hash=${w:-none} headless_hash=${h:-none} match=$match" >> "$out/capture_lines_d.txt"
  [[ "$match" == yes ]]
  python3 scripts/room_gif.py "$dir" "$caps/$pass/deck-$name.gif" --step-ticks "$step"
}
for pass in a b; do
  mkdir -p "$caps/$pass"
  # The same fixtures and tick windows as scripts/make_f01_gate_b_evidence.sh (640x360).
  fixture_gif "$pass" ability-chain carl_prog_dyn_chain_depth_cap 188:3:20 3
  fixture_gif "$pass" ability-reflex cf02_dm_reflex_cues 712:3:30 3
  fixture_gif "$pass" ability-magic-missile cf02_assist_donut_missiles_goblin 8:2:32 2
  fixture_gif "$pass" ability-light-on-your-feet donut_prog_arena_ledge_boost 28:2:37 2
  fixture_gif "$pass" ability-puddle-jumper donut_prog_arena_blink_tour 30:2:40 2
  # Donut's agile motion (DM-A: the run race and the jump race) and the dynamite ring (CP-E outer launch).
  fixture_gif "$pass" agile-run-race dm_run_race_2p 4:2:61 2
  fixture_gif "$pass" agile-jump-race dm_jump_race_2p 6:2:82 2
  fixture_gif "$pass" ring-outer-launch carl_prog_dyn_outer_launch 188:3:22 3
done
names=(ability-chain ability-reflex ability-magic-missile ability-light-on-your-feet ability-puddle-jumper agile-run-race agile-jump-race ring-outer-launch)
for g in "${names[@]}"; do
  cmp "$caps/a/deck-$g.gif" "$caps/b/deck-$g.gif"
  cp "$caps/a/deck-$g.gif" "$out/deck-$g.gif"
done
echo "GATE_D_BYTE_STABLE gifs=${#names[@]} view=640x400 passes=2 result=identical" >> "$out/capture_lines_d.txt"

# 2. Room 4's spectacular route: the throw (tick 346 to 387), the fuse, the blast and the chain (537 and 545).
for pass in a b; do
  for view in 640x360 640x400; do
    extra=()
    [[ "$view" == 640x400 ]] && extra=(--deck)
    dir="$caps/$pass/route-$view"
    line="$(CHECK_TIMED=1 bash scripts/room_capture.sh hazards haz_spectacular 340:6:41 "$dir" "${extra[@]}")"
    [[ "$pass" == a ]] && echo "GATE_D_ROUTE view=$view ${line#ROOM_CAPTURE }" >> "$out/capture_lines_d.txt"
    python3 scripts/room_gif.py "$dir" "$caps/$pass/route-$view.gif" --step-ticks 6
  done
done
cmp "$caps/a/route-640x360.gif" "$caps/b/route-640x360.gif"
cmp "$caps/a/route-640x400.gif" "$caps/b/route-640x400.gif"
cp "$caps/a/route-640x360.gif" "$out/route-room4-spectacular.gif"
cp "$caps/a/route-640x400.gif" "$out/route-room4-spectacular-640x400.gif"
echo "GATE_D_BYTE_STABLE gifs=2 route=room4-spectacular passes=2 result=identical" >> "$out/capture_lines_d.txt"

(cd "$out" && sha256sum ./*.gif ./*.png ./*.txt ./*.md | grep -v ' ./README.md$' | sed 's# \./# #' > SHA256SUMS)
